entries[60831] = { ["name"] = "Katapultteile", ["text"] = "Questgegenstand\nEinzigartig\n\"Die solltet Ihr besser zu Spitz Schleifstein bringen, aber schnell!\"" }
entries[60834] = { ["name"] = "Goldmines Feuertotem", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Benutzt Goldmines Feuertotem neben einer der Lavapfützen am Blutpfad. (5 Sek. Abklingzeit)" }
entries[60835] = { ["name"] = "Erschöpftes Totem", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört ein erschöpftes Totem. (6 Sek. Abklingzeit)" }
entries[60837] = { ["name"] = "Das brennende Herz", ["text"] = "Questgegenstand\nEinzigartig\n\"Au, au! Heiß und fettig!\"" }
entries[60838] = { ["name"] = "Mysteriöse Glückskarte", ["text"] = "Benutzen: Dreht eine Karte um, um in die Zukunft zu sehen.\nVerkaufspreis:" }
entries[60839] = { ["name"] = "Glückskarte", ["text"] = "\"Nicht alles, was glänzt, ist auch Gold. Aber meistens lässt es sich zumindest für Gold verkaufen.\"\nVerkaufspreis:" }
entries[60840] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr habt viele Freunde und nur sehr wenige lebende Feinde.\"\nVerkaufspreis:" }
entries[60841] = { ["name"] = "Glückskarte", ["text"] = "\"Ein Freund bittet um Eure Zeit. Eine Gilde bittet um Euer Geld.\"\nVerkaufspreis:" }
entries[60842] = { ["name"] = "Glückskarte", ["text"] = "\"Euer Fraktionsanführer denkt an Euch.\"\nVerkaufspreis:" }
entries[60843] = { ["name"] = "Glückskarte", ["text"] = "\"Hütet Euch vor einem großen Nachtelfen mit einem blonden Stiefel.\"\nVerkaufspreis:" }
entries[60844] = { ["name"] = "Glückskarte", ["text"] = "\"Ihr werdet bald reich sein.\"\nVerkaufspreis:" }
entries[60845] = { ["name"] = "Glückskarte", ["text"] = "\"Das Leben ist kurz, Ihr solltet mehr riskieren.\"\nVerkaufspreis:" }
entries[60847] = { ["name"] = "Eiskaltes Händchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euer eiskaltes Händchen beschwören oder wieder freigeben." }
entries[60849] = { ["name"] = "Langs Handgranaten", ["text"] = "Questgegenstand\nBenutzen: Tötet sofort jegliche Berserker der Klapperknochen. Kann auch genutzt werden, um einen Knochenanimus der Geißel unschädlich zu machen.\n\"Ein Säckchen mit einfachen handgemachten Bomben.\"" }
entries[60850] = { ["name"] = "Braunfederkiel", ["text"] = "Questgegenstand\n\"Eine große Schwanzfeder von einem der Falken der Gegend.\"" }
entries[60851] = { ["name"] = "Bärenfleischstück", ["text"] = "Questgegenstand\n\"Ein riesiges Stück Fleisch. Davon werden sicher Dutzende satt.\"" }
entries[60852] = { ["name"] = "Instabiler Energieumwandler", ["text"] = "Verkaufspreis:" }
entries[60853] = { ["name"] = "Instabiles Zephyriumsprengpaket", ["text"] = "Benötigt Ingenieurskunst (425)\nBenutzen: Sprengt verschlossene Türen und Kisten auf, die eine Fertigkeit von bis zu 525 im Schlossknacken benötigen\nVerkaufspreis:" }
entries[60854] = { ["name"] = "Plünderang", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenötigt Ingenieurskunst (125)\nBenutzen: Sammelt die Beute von einem nahen Leichnam ein. (10 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[60855] = { ["name"] = "Goblinisches Mini-Hotrod", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (500)\nBenötigt Gobliningenieur\nBenutzen: Beschwört und kontrolliert Euren Krachbummflitzer. (5 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[60856] = { ["name"] = "Metrognom Beziehungsstrahl (NYI)", ["text"] = "Wird beim Anlegen gebunden\nSchmuck\nBenutzen: Lässt einen Gegner makuliner oder femininer erscheinen. (2 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[60857] = { ["name"] = "Geborgene Vorräte", ["text"] = "Questgegenstand\n\"Unverderbliche Waren, die vom Meeresboden geborgen worden sind.\"" }
entries[60858] = { ["name"] = "Goblinbarbecue", ["text"] = "Benötigt Stufe 80\nBenötigt Kochkunst (475)\nBenutzen: Richtet für Eure Gruppe oder Euren Schlachtzug ein Goblinbarbecuefestmahl her! Stellt im Verlauf von 30 Sek. 67500 Gesundheit und 45000 Mana wieder her. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 60 Ausdauer und ein für Euch nützlicher Wert wird um 60 erhöht.\nVerkaufspreis:" }
entries[60859] = { ["name"] = "Aufwendige Scheibe", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Kombiniert die aufwendige Scheibe und den Stab des Sultans, um den Schaft der Sterne herzustellen. (3 Sek. Abklingzeit)" }
entries[60860] = { ["name"] = "Verschnörkeltes Tafelfragment", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Was ist das hier an der Kante? Sieht aus wie… Pygmäenpopel!\"" }
entries[60861] = { ["name"] = "Heiliges Weihrauchfass", ["text"] = "Questgegenstand\nBenutzen: Ermutigt eine zurückgezogene Seele, den Trauerhügel zu verlassen. (5 Sek. Abklingzeit)\n\"Ein kleiner Metallbehälter voller Weihrauch und Gewürze.\"" }
entries[60862] = { ["name"] = "Insigne der Verlassenen", ["text"] = "Questgegenstand" }
entries[60863] = { ["name"] = "Abgetragene Brustplatte", ["text"] = "Questgegenstand\n\"Ein lange vergessenes Stück Rüstung.\"" }
