entries[62348] = { ["name"] = "Terraths Signet des Gleichgewichts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+168 Beweglichkeit\n+252 Ausdauer\nErhöht Eure Meisterschaftswertung um + 112.\nBenötigt Stufe 85\nBenötigt Therazane\n- Respektvoll\nAnlegen: Erhöht die Trefferwertung um 112.\n\"Wenn die Erde still wird, der Lärm verstummt und sich Eure Konzentration verschärft, zielt genau. -Terrath der Beständige\"\nVerkaufspreis:" }
entries[62350] = { ["name"] = "Gorsiks Band der Zerschlagung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+168 Stärke\n+252 Ausdauer\nBenötigt Stufe 85\nBenötigt Therazane\n- Respektvoll\nAnlegen: Erhöht die kritische Trefferwertung um 112.\nAnlegen: Erhöht die Tempowertung um 112.\n\"Die Erde bebt, und Eure Feinde erzittern. Ihr erscheint, und die Zerstörung ist an Eurer Seite. - Gorsik der Tosende\"\nVerkaufspreis:" }
entries[62351] = { ["name"] = "Felsens Ring der Entschlossenheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+168 Stärke\n+252 Ausdauer\nErhöht Eure Meisterschaftswertung um + 112.\nBenötigt Stufe 85\nBenötigt Therazane\n- Respektvoll\nAnlegen: Erhöht Eure Ausweichwertung um 112.\n\"Winde, Erde und Stürme mögen auf Euren Körper prallen, doch allein Euer Wille wird Euch auf den Beinen halten. -Felsen der Ausdauernde\"\nVerkaufspreis:" }
entries[62352] = { ["name"] = "Diamants Ring der Mäßigung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+252 Ausdauer\n+168 Intelligenz\nBenötigt Stufe 85\nBenötigt Therazane\n- Respektvoll\nAnlegen: Erhöht die kritische Trefferwertung um 112.\nAnlegen: Erhöht die Tempowertung um 112.\n\"Alle Seelen zeigen ihre wahre Natur, wenn man ihnen vertraut, selbst wenn das Vertrauen ungerechtfertigt ist. -Diamant der Geduldige\"\nVerkaufspreis:" }
